import{_ as a,a as t,b as i,c as r,d as o,e as s}from"./chunks/news.DV75aeUs.js";import{_ as n,o as l,c as d,a2 as c}from"./chunks/framework.DDY-poMm.js";const y=JSON.parse('{"title":"Trading and market data","description":"","frontmatter":{},"headers":[],"relativePath":"wallet/trading.md","filePath":"wallet/trading.md","lastUpdated":1793861180000}'),p={name:"wallet/trading.md"};function h(m,e,g,f,u,x){return l(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="trading-and-market-data" tabindex="-1">Trading and market data <a class="header-anchor" href="#trading-and-market-data" aria-label="Permalink to &quot;Trading and market data&quot;">​</a></h1><h2 id="trade-tokenized-us-stocks-on-chain" tabindex="-1">Trade tokenized US stocks on-chain <a class="header-anchor" href="#trade-tokenized-us-stocks-on-chain" aria-label="Permalink to &quot;Trade tokenized US stocks on-chain&quot;">​</a></h2><p>Buy and sell xStocks US stocks and ETFs directly with USDC / USDT, with price, slippage and fees shown before ordering. Before signing, the app checks exactly how the trade will change balances and approvals, and stops if anything looks wrong; high slippage triggers a warning and a second confirmation. On-chain trading remains available while the US market is closed, with a clear notice that on-chain prices may deviate.</p><h2 id="professional-market-data" tabindex="-1">Professional market data <a class="header-anchor" href="#professional-market-data" aria-label="Permalink to &quot;Professional market data&quot;">​</a></h2><p>Charts from 15 minutes, 1 hour and 4 hours to daily and weekly, with moving averages, volume and a crosshair; drag and pinch to zoom; the price at the top always matches the latest candle and updates in real time. Below the chart, the order-flow panel shows 24-hour buy/sell counts and live trades. When the US market is closed, the last close time (ET) is shown.</p><h2 id="company-profiles" tabindex="-1">Company profiles <a class="header-anchor" href="#company-profiles" aria-label="Permalink to &quot;Company profiles&quot;">​</a></h2><p>Every stock has a bilingual company profile: company, ticker, industry, type, listing date, exchange, website and description. Profiles are compiled from public information, and websites are only taken from official registrations or verifiable sources.</p><h2 id="news-and-filings" tabindex="-1">News and filings <a class="header-anchor" href="#news-and-filings" aria-label="Permalink to &quot;News and filings&quot;">​</a></h2><p>AI turns public reports into bilingual articles with images. Before publishing, dates and amounts are cross-checked between the two languages, and inconsistent articles are not published. Official company filings from the US SEC are included.</p><h2 id="crypto-quotes" tabindex="-1">Crypto quotes <a class="header-anchor" href="#crypto-quotes" aria-label="Permalink to &quot;Crypto quotes&quot;">​</a></h2><p>The market tab is split into &quot;Stocks | Crypto&quot;. Major coins are quoted from leading exchanges&#39; spot markets, and platform coin prices match our platform. Coin detail pages also have &quot;Profile&quot; and &quot;News&quot; tabs. Crypto is view-only and cannot be traded in the wallet.</p><h2 id="trading-and-market-screens" tabindex="-1">Trading and market screens <a class="header-anchor" href="#trading-and-market-screens" aria-label="Permalink to &quot;Trading and market screens&quot;">​</a></h2><div style="display:flex;flex-wrap:wrap;gap:28px 20px;justify-content:center;margin:32px 0;"><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+a+'" alt="Market · Stocks" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Market · Stocks</b><br>Listed tokenized US stocks and ETFs with 7-day trends </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+t+'" alt="Market · Crypto" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Market · Crypto</b><br>Major coins and platform coin, view-only </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+i+'" alt="Chart" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Chart</b><br>15-minute to weekly candles with MAs, volume and crosshair </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+r+'" alt="Order flow" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Order flow</b><br>24-hour buy/sell split and live trades </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+o+'" alt="Company profile" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Company profile</b><br>Company, industry, listing date, exchange and website </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+s+'" alt="News" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>News</b><br>AI-curated bilingual articles </figcaption></figure></div><div class="tip custom-block"><p class="custom-block-title">About these screenshots</p><p>These are simulator captures of the beta build (Chinese interface); prices and news come from the test environment.</p></div><h2 id="risk-notes" tabindex="-1">Risk notes <a class="header-anchor" href="#risk-notes" aria-label="Permalink to &quot;Risk notes&quot;">​</a></h2><ul><li>Tokenized stocks are issued by the issuer. Holders have no shareholder voting rights, and the issuer may pause transfers in certain cases.</li><li>Confirmed on-chain transactions cannot be reversed.</li></ul>',16)])])}const v=n(p,[["render",h]]);export{y as __pageData,v as default};
